import openpyxl
from openpyxl.utils import get_column_letter

orig = openpyxl.load_workbook('/root/data/workbook.xlsx')
res = openpyxl.load_workbook('/root/output/result.xlsx')

# Ensure same sheets
if orig.sheetnames != res.sheetnames:
    print('Sheetnames differ', orig.sheetnames, res.sheetnames)
    raise SystemExit(1)

# Target cells we intentionally edit
edited = set()
for r in list(range(12,18)) + list(range(19,25)) + list(range(26,32)):
    for c in range(8,13):
        edited.add(("Task", r, c))
for r in range(35,41):
    for c in range(8,13):
        edited.add(("Task", r, c))
for r in range(42,48):
    for c in range(8,13):
        edited.add(("Task", r, c))
for c in range(8,13):
    edited.add(("Task", 50, c))

changed = []

for sheet in orig.sheetnames:
    ws_o = orig[sheet]
    ws_r = res[sheet]
    max_row = max(ws_o.max_row, ws_r.max_row)
    max_col = max(ws_o.max_column, ws_r.max_column)

    for r in range(1, max_row+1):
        for c in range(1, max_col+1):
            key = (sheet, r, c)
            vo = ws_o.cell(r,c).value
            vr = ws_r.cell(r,c).value
            if vo != vr:
                if key in edited:
                    continue
                coord = f"{get_column_letter(c)}{r}"
                changed.append((sheet, coord, vo, vr))

if changed:
    print('Unexpected changes:', len(changed))
    for item in changed[:50]:
        print(item)
    raise SystemExit(1)

print('No unexpected cell value changes detected.')
